import {OBSERVATION_KEY,OBS_PHASES,OBS_KINDS,OBS_CHECKS,newObservations,restoreObservations,observationStep,observationSummary,observationExport} from './observation.js';
const oEsc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),oDialog=document.querySelector('#dialog');
let observationModel,observationError='',oSelected=null,oView='log',oCollapsed=false,oResizeObserver=null;
try{const raw=JSON.parse(window.fixiverseStorage.getItem(OBSERVATION_KEY)||'null');observationModel=raw?restoreObservations(raw):newObservations();}catch{observationModel=newObservations();observationError='Saved observation notes could not be restored. Export a workspace backup before making new marks.';}
const oButton=(text,action,attrs='',quiet=false)=>`<button class="${quiet?'quiet':'btn'}" data-observe="${action}" ${attrs}>${text}</button>`;
const oOptions=(items,value)=>items.map(v=>`<option value="${oEsc(v)}" ${v===value?'selected':''}>${oEsc(v)}</option>`).join('');
function oContext(){const root=document.querySelector('#app');return{screen:(root.querySelector('h1')?.innerText||document.title).slice(0,240),context:`${document.title} | ${root.querySelector('.panel-head')?.innerText||''} | viewport ${innerWidth}x${innerHeight}`.replace(/\s+/g,' ').slice(0,240)};}
function oFormStatus(form,message){let status=form.querySelector('.observation-form-status');if(!status){status=document.createElement('p');status.className='observation-form-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.append(status);}status.textContent=message;}
function oSave(action){const next=observationStep(observationModel,action);window.fixiverseStorage.setItem(OBSERVATION_KEY,JSON.stringify(next));observationModel=next;renderObservationDock();}
function oSession(){return observationModel.sessions.find(s=>s.id===(oSelected||observationModel.active))||observationModel.sessions.at(-1);}
function observationDockSize(dock){if(!dock?.isConnected)return;const warning=document.querySelector('#storage-warning'),offset=warning?.getBoundingClientRect().height||0;dock.style.bottom=`${offset}px`;document.body.style.setProperty('--observation-space',`${dock.getBoundingClientRect().height+offset+16}px`);}
function renderObservationDock(){let dock=document.querySelector('#observation-dock');if(!observationModel.active){dock?.remove();oResizeObserver?.disconnect();oResizeObserver=null;document.body.classList.remove('observation-active');document.body.style.removeProperty('--observation-space');return;}const s=observationModel.sessions.find(x=>x.id===observationModel.active),c=observationSummary(s);if(!dock){dock=document.createElement('aside');dock.id='observation-dock';dock.setAttribute('aria-label','Tutor observation controls');document.body.insertBefore(dock,document.querySelector('#storage-warning'));oResizeObserver=new ResizeObserver(()=>observationDockSize(dock));oResizeObserver.observe(dock);}document.body.classList.add('observation-active');dock.className=`observation-dock ${oCollapsed?'collapsed':''}`;dock.innerHTML=oCollapsed?oButton(`Tutor notes · ${c.ui} UI prompts logged`,'expand','',true):`<div><b>Tutor observation · ${oEsc(s.phase)}</b><small>${c.ui} UI instructions logged · ${c.pendingNotes} marks need detail</small></div><div class="btn-row">${oButton('UI instruction +1','quick')}${oButton('Record a barrier','manage')}${oButton('Device / access checks','checks','',true)}${oButton('Collapse','collapse','',true)}</div>`;observationDockSize(dock);}
function observationStart(){return`<h2 id="observation-title">Watch a little. Learn a lot.</h2><p>Use a learner nickname such as K01. Log only what you observe. No clicks, speech or typed answers are recorded automatically.</p><form id="observation-start"><div class="observation-fields"><label>Visit phase<select name="phase">${oOptions(OBS_PHASES,'Play')}</select></label><label>Test environment<select name="environment">${oOptions(['Not specified','Actual device','Browser viewport simulation'],'Not specified')}</select></label><label>Device label<input name="device" required maxlength="120" placeholder="e.g. Android phone / Windows laptop"></label><label>Browser / version<input name="browser" required maxlength="120" placeholder="e.g. Chrome 141 / Safari"></label><label>Input used<input name="input" maxlength="120" placeholder="Touch, mouse, keyboard, switch…"></label><label>Actual assistive tools / settings<input name="tools" maxlength="120" placeholder="NVDA version…, VoiceOver, 200% zoom, none…"></label></div><p class="lab-small">A resized browser is a viewport simulation. It does not establish actual-phone or screen-reader accessibility.</p><button class="btn" type="submit">Start tutor observation</button></form>`;}
function observationLog(s){const c=observationSummary(s);return`<h2 id="observation-title">A place to improve the app.</h2><p><b>${oEsc(s.device)} / ${oEsc(s.browser)}</b> · ${oEsc(s.phase)} · ${s.endedAt===null?'In progress':'Finished'}. ${oEsc(s.environment)}. Tools: ${oEsc(s.tools||'Not recorded')}.</p><p id="observation-totals">${c.ui} UI instructions logged · ${c.math} math-help marks · ${c.access} access-support marks · ${c.openBlockers} unresolved blockers. These are logged counts; unobserved help is unknown.</p>${s.endedAt===null?`<form id="observation-log"><div class="observation-fields"><label>What kind of barrier or help?<select name="kind">${oOptions(OBS_KINDS,'UI instruction')}</select></label><label>How much did it interrupt?<select name="severity">${oOptions(['Minor','Needs help','Blocker'],'Needs help')}</select></label><label>Occurrences<input name="quantity" type="number" value="1" min="1" max="20" required></label><label>If math help: highest level<select name="helpLevel"><option value="0">0 · No math instruction</option><option value="1">1 · Conceptual prompt</option><option value="2">2 · Strategy / explanation</option><option value="3">3 · Worked answer</option></select></label></div><label>What was the child trying to do?<input name="tried" maxlength="240" placeholder="e.g. Find the next-step button"></label><label>What instruction or support was needed?<input name="help" maxlength="240" placeholder="e.g. I pointed out “Keep my clue”"></label><label>Note / proposed fix<textarea name="note" rows="2" maxlength="240" placeholder="No names or diagnoses. Record the observable issue."></textarea></label><p class="lab-small">The current lesson heading and viewport are attached when you save this mark. Access support (reading text, AAC, keyboard assistance) is separate from math instruction.</p><button class="btn" type="submit">Save this observation</button></form>`:''}<details class="observation-records"><summary>Review ${s.events.length} recorded marks</summary>${s.events.map(e=>`<form class="observation-edit" data-event-id="${oEsc(e.id)}"><p><b>${oEsc(e.kind)} · ${oEsc(e.screen)}</b><br>${oEsc(e.severity)} · ${e.quantity} ${e.voided?'· Excluded from counts':''}</p><label>Tried<input name="tried" maxlength="240" value="${oEsc(e.tried)}"></label><label>Help needed<input name="help" maxlength="240" value="${oEsc(e.help)}"></label><label>Note<input name="note" maxlength="240" value="${oEsc(e.note)}"></label><label>Fix / retest state<select name="status">${oOptions(['Open','Fixed - needs retest','Retested'],e.status)}</select></label><div class="btn-row"><button class="quiet" type="submit">Save detail</button>${oButton(e.voided?'Restore this mark':'Exclude mistaken mark','void',`data-id="${oEsc(e.id)}"`,true)}</div></form>`).join('')||'<p>No marks recorded. This is not evidence that no barriers occurred.</p>'}</details><div class="btn-row">${oButton('Device / access checks','checks','',true)}${oButton('Download session summary CSV','sessions','',true)}${oButton('Download barrier log CSV','barriers','',true)}${s.endedAt===null?oButton('Finish this observation','end'):oButton('Start another visit','new','',true)}</div>`;}
function observationChecks(s){const c=observationSummary(s);return`<h2 id="observation-title">Check what they actually use.</h2><p>${oEsc(s.device)} / ${oEsc(s.browser)} · ${oEsc(s.environment)} · Tools: ${oEsc(s.tools||'Not recorded')}.</p><p id="observation-check-counts">${c.checksPass} passed · ${c.checksBarrier} barriers · ${c.checksNotRun} not run. These are preliminary checks, not WCAG certification.</p>${OBS_CHECKS.map(([key,label,task])=>{const old=s.checks[key]||{status:'Not run',note:''};return`<form class="observation-check" data-check="${key}"><h3>${oEsc(label)}</h3><p>${oEsc(task)}</p><label>Observed result<select name="status">${oOptions(['Not run','Pass','Barrier','Not applicable'],old.status)}</select></label><label>What you tried / evidence / reason not applicable<textarea name="note" maxlength="240" rows="2">${oEsc(old.note)}</textarea></label><button class="quiet" type="submit">Save ${oEsc(label.toLowerCase())} check</button></form>`;}).join('')}<div class="btn-row">${oButton('Back to observation marks','manage','',true)}${oButton('Download device checks CSV','checks-export','',true)}</div>`;}
function showObservation(view='log',id=null){if(id)oSelected=id;oView=view;const s=oSession();oDialog.className='storybook-dialog observation-dialog';oDialog.setAttribute('aria-labelledby','observation-title');oDialog.innerHTML=`<div class="observation-dialog-top"><span class="eyebrow">FOR THE TUTOR / SMALL PILOT</span>${oButton('Close ×','close','aria-label="Close tutor observation"',true)}</div>${observationModel.sessions.length?`<label class="observation-session-select">Saved observation visit<select id="observation-session">${observationModel.sessions.map(x=>`<option value="${x.id}" ${s?.id===x.id?'selected':''}>${oEsc(x.phase)} · ${oEsc(x.device)} · ${new Date(x.startedAt).toLocaleDateString()}${x.endedAt===null?' · active':''}</option>`).join('')}</select></label>`:''}${observationError?`<p class="result soft" role="alert">${oEsc(observationError)}</p>`:''}${view==='new'||!s?observationStart():view==='checks'?observationChecks(s):observationLog(s)}<p id="observation-status" role="status" aria-live="polite"></p>`;if(!oDialog.open)oDialog.showModal();oDialog.scrollTop=0;oDialog.querySelector('h2').tabIndex=-1;oDialog.querySelector('h2').focus({preventScroll:true});}
function observationSection(){const s=observationModel.sessions.at(-1),c=s?observationSummary(s):null;return`<section class="tutor-section observation-section"><div class="section-heading"><h2>Observe usability, without guessing.</h2><span>Tutor-entered notes · private to this learner</span></div><p>Mark every time you give interface instructions. Keep math help and access support separate. Record actual-device and assistive-tool checks; untested checks stay Not run.</p>${s?`<p>Latest visit: ${oEsc(s.phase)} · ${oEsc(s.device)} · ${c.ui} UI instructions logged · ${c.pendingNotes} marks need detail · ${c.checksNotRun} device checks not run.</p>`:'<p>No observation sessions recorded.</p>'}<div class="btn-row">${oButton(observationModel.active?'Open current observation':s?'Review observation notes':'Start tutor observation','manage')}${s&&!observationModel.active?oButton('Start another visit','new','',true):''}${s?oButton('Download barrier log CSV','barriers','',true):''}</div><p class="lab-small">Use K01 to K08 aliases to match the testing kit. Downloaded records contain learning observations; keep them private. No check is marked passed automatically.</p></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-observe]');if(!b)return;const a=b.dataset.observe;observationError='';try{if(a==='close'){oDialog.close();return;}if(a==='collapse'||a==='expand'){oCollapsed=a==='collapse';renderObservationDock();document.querySelector('#observation-dock button')?.focus({preventScroll:true});return;}if(a==='quick'){oSave({type:'log',kind:'UI instruction',...oContext()});document.querySelector('#announcement').textContent='One interface instruction marked. Add what happened in the tutor observation notes.';document.querySelector('[data-observe="quick"]')?.focus({preventScroll:true});return;}if(['manage','new','checks'].includes(a)){showObservation(a==='new'?'new':a==='checks'?'checks':'log');return;}if(['sessions','barriers','checks-export'].includes(a)){const alias=window.fixiverseProfiles.list().find(p=>p.id===window.fixiverseProfiles.active()).alias,result=observationExport(alias,observationModel),key=a==='checks-export'?'checks':a,url=URL.createObjectURL(new Blob([result[key]],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`fixiverse-observation-${key}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#announcement').textContent='Observation CSV downloaded.';return;}const s=oSession();if(a==='end'){oSave({type:'end',session:s.id});oDialog.close();location.hash='tutor';window.fixiverseTutor.show();return;}if(a==='void'){const event=s.events.find(x=>x.id===b.dataset.id);oSave({type:'edit',session:s.id,id:event.id,voided:!event.voided});showObservation();}}catch(err){observationError=err.message;const status=oDialog.open?oDialog.querySelector('#observation-status'):document.querySelector('#announcement');status.textContent=observationError;}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('#observation-start,#observation-log,.observation-edit,.observation-check'))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));try{if(form.id==='observation-start'){oSave({type:'start',...data});oSelected=observationModel.active;oDialog.close();location.hash='tutor';window.fixiverseTutor.show();document.querySelector('#announcement').textContent='Tutor observation started. Open the child’s activity, then use the observation controls when help is needed.';return;}const s=oSession();if(form.id==='observation-log')oSave({type:'log',session:s.id,...data,quantity:+data.quantity,helpLevel:+data.helpLevel,...oContext()});else if(form.classList.contains('observation-edit'))oSave({type:'edit',session:s.id,id:form.dataset.eventId,...data});else oSave({type:'check',session:s.id,key:form.dataset.check,...data});if(form.id==='observation-log'){showObservation('log');oDialog.querySelector('[name="kind"]').focus();oDialog.querySelector('#observation-status').textContent='Observation saved with the current screen location.';}else{oFormStatus(form,'Saved. Only observed results count.');const c=observationSummary(oSession()),counter=oDialog.querySelector('#observation-check-counts');if(counter)counter.textContent=`${c.checksPass} passed · ${c.checksBarrier} barriers · ${c.checksNotRun} not run. Preliminary checks, not WCAG certification.`;}}catch(err){oFormStatus(form,err.message);}});
document.addEventListener('change',e=>{if(e.target.id==='observation-session'){oSelected=e.target.value;showObservation(oView,oSelected);}});
window.addEventListener('resize',()=>observationDockSize(document.querySelector('#observation-dock')));
window.addEventListener('fixiverse-storage-warning',()=>observationDockSize(document.querySelector('#observation-dock')));
window.fixiverseObservation={section:observationSection,beginPilot:s=>{if(observationModel.active){const current=observationModel.sessions.find(v=>v.id===observationModel.active);if(current.phase!=='Play'||s.play.observation!==current.id)throw Error('Finish the existing observation before starting this guided play visit.');return observationModel.active;}oSave({type:'start',phase:'Play',device:s.device,browser:s.browser,input:s.input,tools:s.tools,environment:s.environment});return observationModel.active;},endPilot:id=>{if(id&&observationModel.active===id)oSave({type:'end',session:id});}};renderObservationDock();
